INSERT INTO `papers` VALUES (1,4,'Attention Is All You Need','Các mô hình chuỗi thống trị các phương pháp tiên tiến nhất trong mô hình hóa ngôn ngữ và các bài toán chuyển đổi từ chuỗi sang chuỗi. Trong nghiên cứu này, chúng tôi đề xuất kiến trúc Transformer — một kiến trúc mạng thuần túy dựa trên cơ chế chú ý, hoàn toàn không sử dụng tính toán tuần tự hay tích chập. Các thử nghiệm trên hai bài toán dịch máy cho thấy những mô hình này có chất lượng vượt trội, song song hóa tốt hơn và cần ít thời gian huấn luyện hơn đáng kể. Mô hình của chúng tôi đạt 28,4 BLEU trên bài toán dịch tiếng Anh sang tiếng Đức WMT 2014, cải thiện hơn 2 BLEU so với các kết quả tốt nhất hiện có.','2026-04-10 08:15:00',11,'completed',38,NULL,'2026-04-10 08:15:38',NULL,NULL),(2,4,'BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding','Chúng tôi giới thiệu một mô hình mới gọi là BERT (Bidirectional Encoder Representations from Transformers). BERT được thiết kế để tiền huấn luyện các biểu diễn sâu hai chiều từ văn bản không có nhãn, bằng cách điều kiện hóa đồng thời trên cả ngữ cảnh trái và phải ở mọi lớp. Kết quả là mô hình BERT đã được tiền huấn luyện có thể được tinh chỉnh chỉ với một lớp đầu ra bổ sung để tạo ra các mô hình tiên tiến nhất cho nhiều tác vụ NLP, bao gồm hỏi đáp và suy luận ngôn ngữ, mà không cần thay đổi đáng kể kiến trúc đặc thù cho từng tác vụ.','2026-04-11 09:30:00',16,'completed',55,NULL,'2026-04-11 09:30:55',NULL,NULL),(3,4,'Deep Residual Learning for Image Recognition','Chúng tôi trình bày một framework học tàn dư (residual learning) để làm dễ dàng hơn việc huấn luyện các mạng nơ-ron rất sâu. Chúng tôi tái công thức hóa các lớp một cách rõ ràng để học các hàm tàn dư liên quan đến đầu vào của lớp, thay vì học các hàm không có tham chiếu. Chúng tôi cung cấp bằng chứng toàn diện cho thấy những mạng tàn dư này dễ tối ưu hơn và có thể đạt được độ chính xác cao hơn từ độ sâu tăng đáng kể. Trên tập dữ liệu ImageNet, chúng tôi đánh giá các mạng tàn dư với độ sâu lên đến 152 lớp.','2026-04-12 14:00:00',12,'completed',47,NULL,'2026-04-12 14:00:47',NULL,NULL),(4,4,'Generative Adversarial Networks','Chúng tôi đề xuất một framework mới để ước tính các mô hình sinh thông qua một quá trình đối kháng, trong đó chúng tôi đồng thời huấn luyện hai mô hình: một mô hình sinh G nắm bắt phân phối dữ liệu, và một mô hình phân biệt D ước tính xác suất rằng một mẫu đến từ dữ liệu huấn luyện thay vì G. Quy trình huấn luyện cho G là tối đa hóa xác suất D mắc lỗi. Framework này tương ứng với một trò chơi minimax hai người.','2026-04-13 10:00:00',9,'completed',29,NULL,'2026-04-13 10:00:29',NULL,NULL),(5,4,'GPT-4 Technical Report','Chúng tôi báo cáo về GPT-4, một mô hình đa phương thức quy mô lớn có thể chấp nhận đầu vào hình ảnh và văn bản, đồng thời tạo ra đầu ra văn bản. Mặc dù kém hơn con người trong nhiều tình huống thực tế, GPT-4 thể hiện hiệu suất ở mức con người trên nhiều bài kiểm tra học thuật và chuyên nghiệp. Ví dụ, mô hình vượt qua kỳ thi luật sư mô phỏng ở khoảng top 10% số người thi, trái ngược với GPT-3.5, vốn đạt điểm quanh mức bottom 10%.','2026-04-14 11:30:00',84,'completed',180,NULL,'2026-04-14 11:33:00',NULL,NULL),(6,5,'A Survey on Large Language Models','Kể từ sự ra đời của ChatGPT, các mô hình ngôn ngữ lớn (LLMs) đã thu hút sự chú ý đáng kể từ cả giới học thuật lẫn ngành công nghiệp. Sức mạnh đặc biệt của các LLMs nằm ở khả năng hiểu và tạo ngôn ngữ tự nhiên giống con người. Bài khảo sát này cung cấp tổng quan toàn diện về nền tảng của LLMs, bao gồm lịch sử phát triển, kỹ thuật tiền huấn luyện, các phương pháp thích nghi và sử dụng, cũng như các ứng dụng tiêu biểu.','2026-04-15 09:00:00',31,'completed',75,NULL,'2026-04-15 09:01:15',NULL,NULL),(7,5,'Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks','Chúng tôi khám phá một phương pháp kết hợp bộ nhớ tham số và phi tham số để tạo ngôn ngữ — các nhiệm vụ đòi hỏi nhiều kiến thức tức là sử dụng các mô hình seq2seq kết hợp với truy xuất thưa từ một tài liệu Wikipedia dày đặc. Mô hình của chúng tôi, Retrieval-Augmented Generation (RAG), đạt được kết quả tiên tiến nhất trên ba bài kiểm tra hỏi đáp miền mở.','2026-04-16 10:00:00',14,'completed',42,NULL,'2026-04-16 10:00:42',NULL,NULL),(8,5,'Constitutional AI: Harmlessness from AI Feedback','Chúng tôi giới thiệu một phương pháp để huấn luyện các hệ thống AI vô hại sử dụng chính AI làm phản hồi. Phương pháp bao gồm hai giai đoạn: một giai đoạn học có giám sát, trong đó một mô hình tạo ra và sau đó tự phê bình và sửa đổi các phản hồi của nó dựa trên một tập hợp các nguyên tắc; và một giai đoạn học tăng cường từ phản hồi của AI (RLAIF).','2026-04-17 13:00:00',17,'completed',53,NULL,'2026-04-17 13:00:53',NULL,NULL),(9,5,'LLaMA: Open and Efficient Foundation Language Models','Chúng tôi giới thiệu LLaMA, một bộ các mô hình ngôn ngữ nền tảng từ 7B đến 65B tham số. Chúng tôi huấn luyện các mô hình của mình trên hàng nghìn tỷ token và cho thấy rằng có thể huấn luyện các mô hình tiên tiến chỉ sử dụng các bộ dữ liệu có sẵn công khai, mà không cần sử dụng các bộ dữ liệu độc quyền và không thể tiếp cận. Mô hình LLaMA-13B vượt qua GPT-3 (175B) trên hầu hết các bài kiểm tra.','2026-04-18 08:30:00',21,'completed',66,NULL,'2026-04-18 08:31:06',NULL,NULL),(10,5,'Scaling Laws for Neural Language Models','Chúng tôi nghiên cứu các quy luật thực nghiệm cho hiệu suất mô hình ngôn ngữ theo quy mô. Hiệu suất mô hình cải thiện khá trơn tru như một hàm bậc lũy thừa của quy mô mô hình, kích thước tập dữ liệu và lượng tính toán được sử dụng cho quá trình huấn luyện. Một số xu hướng khác tác động ít nhất: kiến trúc mô hình, chiều rộng so với độ sâu trong giới hạn hợp lý và kích hoạt cụ thể.','2026-04-19 11:00:00',67,'completed',155,NULL,'2026-04-19 11:02:35',NULL,NULL),(11,6,'AlphaFold: Improved protein structure prediction using potentials from deep learning','Chúng tôi mô tả một phương pháp mới sử dụng thông tin tiến hóa, vật lý và hình học của cấu trúc protein để tạo ra một tiềm năng chính xác hơn nhằm dự đoán cấu trúc protein. Tiềm năng này được sử dụng trong quá trình tìm kiếm cấu trúc được hướng dẫn bởi gradient. Chúng tôi cũng mô tả các cải tiến trong kiến trúc mạng nơ-ron, cụ thể là với kiến trúc attention có cấu trúc.','2026-04-20 09:00:00',10,'completed',35,NULL,'2026-04-20 09:00:35',NULL,NULL),(12,6,'CRISPR-Cas9 for medical genetic screens in human cells','Kỹ thuật chỉnh sửa gen CRISPR-Cas9 có tiềm năng to lớn trong y học. Bài báo này trình bày kết quả của các màn hình di truyền y tế quy mô lớn trong tế bào người sử dụng CRISPR-Cas9 để xác định các gen liên quan đến kháng thuốc và nhạy cảm với thuốc trong ung thư. Phương pháp của chúng tôi cho phép xác định hàng trăm gen ứng viên, cung cấp cơ sở cho các mục tiêu điều trị mới.','2026-04-21 10:00:00',8,'completed',24,NULL,'2026-04-21 10:00:24',NULL,NULL),(13,6,'Moderna mRNA-1273 COVID-19 Vaccine Efficacy Trial Results','Chúng tôi báo cáo kết quả thử nghiệm hiệu quả của vaccine COVID-19 dựa trên mRNA mã hóa glycoprotein gai SARS-CoV-2 được ổn định trước khi tiêm chủng. Thử nghiệm ngẫu nhiên, đối chứng giả dược, gồm 30.420 người lớn đăng ký. Vaccine mRNA-1273 có hiệu quả 94,1% trong việc ngăn ngừa COVID-19 có triệu chứng, bao gồm COVID-19 nặng.','2026-04-22 14:00:00',13,'completed',45,NULL,'2026-04-22 14:00:45',NULL,NULL),(14,6,'The Human Microbiome Project: A community resource for the healthy human microbiome','Dự án Microbiome Con người (HMP) đã lấy mẫu từ 242 tình nguyện viên người lớn khỏe mạnh tại 15–18 vị trí cơ thể lên đến ba lần, phân tích mẫu bằng cách giải trình tự 16S rRNA và toàn bộ shotgun metagenome. Kết quả cho thấy sự đa dạng đáng kể giữa các cá nhân và vị trí cơ thể, đồng thời xác định danh mục gen microbiome cốt lõi.','2026-04-23 09:00:00',18,'completed',54,NULL,'2026-04-23 09:00:54',NULL,NULL),(15,6,'Molecular mechanisms of SARS-CoV-2 infection and pathogenesis','Bài tổng quan này tóm tắt các cơ chế phân tử của quá trình nhiễm và gây bệnh SARS-CoV-2. Chúng tôi thảo luận về cơ chế xâm nhập của virus, bao gồm liên kết thụ thể ACE2 và kích hoạt protein S, cũng như cơ chế phân tử của phản ứng miễn dịch và bệnh nặng. Hiểu biết về các cơ chế này rất quan trọng để phát triển các chiến lược điều trị và phòng ngừa.','2026-04-24 11:30:00',22,'completed',60,NULL,'2026-04-24 11:31:00',NULL,NULL),(16,7,'Bitcoin: A Peer-to-Peer Electronic Cash System','Một hệ thống tiền điện tử hoàn toàn ngang hàng cho phép gửi thanh toán trực tuyến từ bên này sang bên kia mà không cần thông qua bất kỳ tổ chức tài chính nào. Chữ ký số giải quyết một phần vấn đề, nhưng lợi ích chính bị mất đi nếu vẫn cần một bên đáng tin cậy để ngăn chi tiêu đôi. Chúng tôi đề xuất giải pháp cho vấn đề chi tiêu đôi bằng cách sử dụng mạng ngang hàng.','2026-04-25 08:00:00',9,'completed',22,NULL,'2026-04-25 08:00:22',NULL,NULL),(17,7,'Ethereum: A Next-Generation Smart Contract and Decentralized Application Platform','Satoshi Nakamoto đã phát triển Bitcoin vào năm 2008 như là một ứng dụng đột phá, nhưng giao thức Bitcoin có những giới hạn quan trọng. Ethereum giải quyết những giới hạn này bằng cách cung cấp một blockchain có ngôn ngữ lập trình Turing đầy đủ tích hợp sẵn, cho phép bất kỳ ai cũng có thể viết hợp đồng thông minh và ứng dụng phi tập trung.','2026-04-26 09:30:00',36,'completed',88,NULL,'2026-04-26 09:31:28',NULL,NULL),(18,7,'Zero Trust Security: A Framework for Network Architecture and Access Control','Kiến trúc bảo mật Zero Trust loại bỏ khái niệm tin tưởng ngầm định truyền thống và yêu cầu xác thực liên tục của tất cả người dùng và thiết bị. Bài báo này trình bày một framework toàn diện cho kiến trúc Zero Trust, bao gồm các nguyên tắc cơ bản, mô hình triển khai và thách thức thực tế trong việc áp dụng cho doanh nghiệp.','2026-04-27 10:00:00',15,'processing',NULL,NULL,'2026-04-27 10:00:00',NULL,NULL),(19,7,'The Evolution of DevOps: Practices, Tools, and Challenges in Modern Software Development','DevOps đã thay đổi đáng kể cách phần mềm được phát triển và triển khai. Bài nghiên cứu này khảo sát sự phát triển của thực hành DevOps qua các năm, từ các nguyên tắc ban đầu đến các pipeline CI/CD hiện đại. Chúng tôi phân tích 500+ tổ chức về việc áp dụng DevOps, xác định các thực hành tốt nhất và thách thức phổ biến.','2026-04-28 11:00:00',18,'completed',55,NULL,'2026-04-28 11:00:55',NULL,NULL),(20,7,'Cloud Computing: State-of-the-Art and Research Challenges','Điện toán đám mây đã trở thành nền tảng của hạ tầng CNTT hiện đại. Bài khảo sát này trình bày tổng quan về kiến trúc, mô hình dịch vụ (IaaS, PaaS, SaaS) và mô hình triển khai của điện toán đám mây. Chúng tôi cũng thảo luận về các vấn đề nghiên cứu còn tồn tại, bao gồm bảo mật, quản lý tài nguyên và điện toán biên.','2026-04-29 09:00:00',25,'completed',72,NULL,'2026-04-29 09:01:12',NULL,NULL),(21,8,'Big Data Analytics: Methods and Applications','Dữ liệu lớn đang thay đổi cách chúng ta hiểu và phân tích thông tin. Bài báo này khảo sát các phương pháp phân tích dữ liệu lớn hiện đại, bao gồm xử lý theo lô với Hadoop MapReduce, xử lý luồng với Apache Spark và Flink, cũng như các kỹ thuật học máy áp dụng trên quy mô lớn. Chúng tôi thảo luận về các ứng dụng thực tế trong y tế, tài chính và giao thông.','2026-04-30 08:30:00',22,'completed',63,NULL,'2026-04-30 08:31:03',NULL,NULL),(22,8,'Machine Learning for Beginners: A Comprehensive Introduction','Bài báo này cung cấp một giới thiệu toàn diện về học máy cho người mới bắt đầu. Chúng tôi trình bày các thuật toán học có giám sát cơ bản như hồi quy tuyến tính, cây quyết định và máy vector hỗ trợ; các thuật toán học không có giám sát như phân cụm k-means và PCA; và giới thiệu về mạng nơ-ron sâu. Mỗi thuật toán được minh họa bằng ví dụ thực tế.','2026-05-01 09:00:00',28,'completed',80,NULL,'2026-05-01 09:01:20',NULL,NULL),(23,8,'Deep Learning with PyTorch: A Complete Tutorial','Hướng dẫn toàn diện về deep learning sử dụng framework PyTorch. Bài báo bao gồm từ các khái niệm cơ bản về tensor và autograd, đến việc xây dựng và huấn luyện các mạng nơ-ron sâu phức